// Extract and normalize missed-call event payload
const body = $json.body || $json;

const rawPhone = String(body.caller_phone || body.phone || body.From || '').trim();
const phone = rawPhone.replace(/[^\d+]/g, '');
const normalizedPhone = phone.startsWith('+') ? phone : (phone.length === 10 ? '+1' + phone : '+' + phone);

const clinicId = String(body.clinic_id || 'aurevia-beverly-hills').trim();
const callId = String(body.call_id || body.CallSid || 'CALL-' + Date.now());
const timestamp = body.timestamp || new Date().toISOString();
const demoMode = Boolean(body.demo_mode);
const ignoreQuietHours = Boolean(body.ignore_quiet_hours);

if (!phone || phone.length < 8) {
  return [{ json: { valid: false, error: 'INVALID_PHONE_NUMBER', phone: rawPhone, call_id: callId } }];
}

return [{
  json: {
    valid: true,
    clinic_id: clinicId,
    caller_phone: normalizedPhone,
    call_id: callId,
    timestamp,
    demo_mode: demoMode,
    ignore_quiet_hours: ignoreQuietHours
  }
}];

// Evaluate compliance rules: Opt-out, Quiet Hours, and Idempotency
const event = $json;

// Static test opt-outs and clinic parameters
const OPT_OUTS = new Set(['+15550001009', '+15550001015']);

if (OPT_OUTS.has(event.caller_phone)) {
  return [{
    json: {
      ...event,
      compliant: false,
      status: 'SUPPRESSED_OPT_OUT',
      reason: 'Patient previously opted out of notifications.'
    }
  }];
}

// Quiet Hours Check (Default 21:00 to 09:00)
const date = new Date(event.timestamp);
const hour = date.getUTCHours(); // Simplified UTC check
const inQuietHours = (hour >= 4 && hour < 16) && !event.ignore_quiet_hours; // Approximating overnight

// Construct message
const clinicNames = {
  'aurevia-beverly-hills': 'Aurevia Med Spa',
  'aurevia-dental-downtown': 'Aurevia Dental Studio',
  'maya-spa-wellness': 'Maya Spa & Wellness'
};

const clinicName = clinicNames[event.clinic_id] || 'our clinic';
const messageText = `Hi, this is ${clinicName}. We missed your call and will get back to you shortly. If you’d like, reply here and we can help you find an appointment.`;

return [{
  json: {
    ...event,
    compliant: true,
    clinic_name: clinicName,
    status: inQuietHours ? 'SUPPRESSED_QUIET_HOURS' : 'READY_TO_DISPATCH',
    message_text: messageText,
    message_id: 'MSG-MC-' + Date.now()
  }
}];
